/**
 * Standalone room site builder (D-038). Copied unchanged into each standalone store as shopify/build.mjs by
 * LoW90/mfo-mLintelligence scripts/standalone.mjs. Do not edit it in a store: change it there and re-run that script.
 *
 * Reads shopify/catalog.json (the store's data, written by scripts/standalone.mjs from portfolio/rooms.json and
 * portfolio/standalone.json) and the store's own images/ folder, and writes the whole Shopify theme under shopify/theme,
 * the product import CSV and the upload zips. The look comes from the parent store: its stylesheet and fonts
 * (shopify/src/parent.css, shopify/src/fonts) and its header, first screen and footer layout (PROFILES below).
 *
 *   node build.mjs           build theme/, products/ and dist/
 *   node build.mjs --check   exit 1 if theme/ or products/ differ from a fresh build
 *
 * Photographs and films: only the store's own original files in images/ (named in images/README.md), or what the owner
 * picks in the theme editor. A missing photograph leaves a plain toned frame, never a drawing.
 */
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {execFileSync} from 'node:child_process';

const root = path.dirname(fileURLToPath(import.meta.url));
const repo = path.resolve(root, '..');
const theme = path.join(root, 'theme');
export const loadCatalog = () => JSON.parse(fs.readFileSync(path.join(root, 'catalog.json'), 'utf8'));

/** Same shape as the other stores' loadResearch(), so the sister-store catalog check can read this store too. */
export function loadResearch(c = loadCatalog()) {
  return {products: c.products.map(p => ({id: p.handle, name: p.name, brand: p.brand, kind: p.kind, price: p.price}))};
}

const esc = s => String(s ?? '').replace(/[&<>"']/g, ch => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[ch]));
const lq = s => esc(s).replace(/'/g, '&#39;');
const pad = i => String(i + 1).padStart(2, '0');
const slug = name => String(name).toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const sid = h => h.replace(/[^a-z0-9]+/g, '_');
const longDate = d => new Date(d + 'T00:00:00Z').toLocaleDateString('en-US', {day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC'});
/** The first dollar amount in a price snapshot, for sorting. "From $20,160" -> 20160. */
export const priceValue = s => { const m = String(s).match(/\$\s?([\d,]+(?:\.\d+)?)/); return m ? Number(m[1].replace(/,/g, '')) : null; };
const schema = obj => `{% schema %}\n${JSON.stringify(obj, null, 2)}\n{% endschema %}\n`;
const GEN = '{%- comment -%} Generated by shopify/build.mjs from catalog.json. Do not edit; rebuild. {%- endcomment -%}\n';

/* ---------- media: the store's own original files ---------- */

/** The images/ slots. Each is optional; the build bundles whatever exists. */
export function mediaSlots(c) {
  return [
    {file: 'hero.webp', use: 'Hero photograph (about 2400 x 1350), also the film poster'},
    {file: 'hero-film.mp4', use: 'Hero film, a silent 8 to 15 second loop (H.264, about 1920 x 1080)'},
    {file: 'hero-film.webm', use: 'Hero film, WebM copy of the same loop'},
    {file: 'room-film.mp4', use: `"${c.film.title}" film for the middle of the page (H.264, about 1600 x 1000)`},
    {file: 'room-film.webm', use: 'The same middle film as WebM'},
    {file: 'room-film.webp', use: 'Poster frame for the middle film'},
    ...c.makers.flatMap(m => [
      {file: `maker-${slug(m.name)}.webp`, use: `${m.name} tile photograph (about 1200 x 1500, portrait)`},
      {file: `maker-${slug(m.name)}.mp4`, use: `${m.name} tile film (optional, silent loop)`},
    ]),
    ...((c.inspiration && c.inspiration.films) || []).flatMap(f => [
      {file: `${f.file}.mp4`, use: `"${f.title}" inspiration film (H.264, click to play)`},
      {file: `${f.file}.webm`, use: `"${f.title}" inspiration film, WebM copy`},
      {file: `${f.file}.webp`, use: `Poster frame for "${f.title}"`},
    ]),
    ...c.products.map(p => ({file: `product-${p.handle}.webp`, use: `${p.brand} ${p.name} product photograph (about 1600 x 1200)`})),
  ];
}
const imagesDir = path.join(repo, 'images');
const has = f => fs.existsSync(path.join(imagesDir, f));
const asset = f => `{{ '${f}' | asset_url }}`;

/* ---------- parent profiles: header, first screen and footer in the parent store's own markup ---------- */

