    hero: c => `<section class="hero" id="home" aria-labelledby="heroTitle"><div class="hero-photo" aria-hidden="true"></div>${heroFilm(c, 'hero-film')}<div class="hero-shade"></div><div class="hero-inner container"><div class="hero-content"><div class="eyebrow hero-eyebrow"><span class="gold-line"></span> ${esc(c.kicker.toUpperCase())}</div><h1 id="heroTitle">${c.heroLines.map((l, i) => i === c.heroLines.length - 1 && i > 0 ? `<em>${esc(l)}</em>` : esc(l)).join('<br>')}</h1><p>${esc(c.intro)}</p><div class="hero-cta"><a class="btn btn-gold" href="#shop" data-mf-cta="explore">See the ${c.products.length} picks <span aria-hidden="true">→</span></a><a class="hero-link" href="#makers">Meet the makers <span aria-hidden="true">→</span></a></div><div class="hero-under">${c.trust.slice(0, 2).map(t => `<span class="mini-trust">◇ ${esc(t.title)}</span>`).join('')}</div></div><div class="hero-bottom"><span>01 / ${esc(c.short.toUpperCase())}</span><span>EXPLORE THE PICKS <span aria-hidden="true">↓</span></span></div></div>${mediaNote(c, 'mf-site__credit')}</section>`,
