const listSection = (c, name, kind) => `${GEN}<div class="mf-room mf-site__page"><section class="mf-room__band"><div class="mf-room__shell">
${kind === 'collection' ? `  <div class="mf-room__head"><div><p class="mf-room__eyebrow mf-room__eyebrow--gold">${esc(c.name)}</p><h1>{{ collection.title | default: 'Product library' | escape }}</h1></div><p>Every researched piece, with dated prices and the merchant that sells it.</p></div>
  {%- assign mf_list = collection.products -%}`
    : kind === 'search' ? `  <div class="mf-room__head"><div><p class="mf-room__eyebrow mf-room__eyebrow--gold">Search</p><h1>{% if search.performed %}Results for “{{ search.terms | escape }}”{% else %}Search the collection{% endif %}</h1></div>
  <form action="{{ routes.search_url }}" method="get" role="search" class="mf-site__search"><label for="mf-search-q">Search</label><input id="mf-search-q" type="search" name="q" value="{{ search.terms | escape }}" placeholder="Maker or piece"><button type="submit">Search</button></form></div>
  {%- assign mf_list = search.results -%}`
    : `  <div class="mf-room__head"><div><p class="mf-room__eyebrow mf-room__eyebrow--gold">${esc(c.name)}</p><h1>Collections</h1></div></div>`}
${kind === 'collections' ? `  <ul class="mf-room__guide">{%- for col in collections -%}<li><b><a href="{{ col.url }}">{{ col.title | escape }}</a></b>{{ col.products_count }} pieces</li>{%- else -%}<li><b><a href="{{ routes.all_products_collection_url }}">All pieces</a></b>Every researched piece.</li>{%- endfor -%}</ul>`
    : `  {%- if mf_list.size > 0 -%}<div class="mf-room__grid">{%- for p in mf_list -%}{%- if p.object_type == 'product' or p.handle -%}{% render '${c.prefix}-card', handle: p.handle %}{%- endif -%}{%- endfor -%}</div>
  {%- else -%}<p class="mf-site__empty">${kind === 'search' ? '{% if search.performed %}Nothing matched. Try a maker name.{% else %}Type a maker or piece above.{% endif %}' : 'No pieces in this collection yet.'} <a href="{{ routes.root_url }}#shop">See the full collection</a></p>{%- endif -%}`}
</div></section></div>
${schema({name, settings: []})}`;

const simpleSection = (c, name, body) => `${GEN}<div class="mf-room mf-site__page"><section class="mf-room__band"><div class="mf-room__shell mf-site__prose">
${body}
</div></section></div>
${schema({name, settings: []})}`;

/* ---------- styles and script ---------- */

function siteCss(c) {
  const t = c.theme, l = c.look;
  return `
/* ---- ${c.name}: standalone room store (shopify/build.mjs). Parent stylesheet above, room components below. ---- */
:root{--mf-ink:${t.ink};--mf-muted:${t.muted};--mf-line:${t.line};--mf-surface:${t.surface};--mf-accent:${t.accent};--mf-dark:${l.dark};--mf-band:${l.band};--mf-serif:${l.serif}}
${fs.readFileSync(path.join(root, 'src/room.css'), 'utf8')}`;
}

/** The store script, with the vendored intelligence bundle in front exactly as intelligence/sync.mjs writes it. */
function siteJs() {
  const source = fs.readFileSync(path.join(root, 'src/site.js'), 'utf8'), intel = path.join(repo, 'intelligence');
  if (!fs.existsSync(path.join(intel, 'config.json'))) return source;
  const config = JSON.parse(fs.readFileSync(path.join(intel, 'config.json'), 'utf8'));
  const start = '/* MFO_INTERNAL_LEARNING_START */', end = '/* MFO_INTERNAL_LEARNING_END */';
  return `${start}\n${fs.readFileSync(path.join(intel, 'core.cjs'), 'utf8')}\n${fs.readFileSync(path.join(intel, 'browser.js'), 'utf8')}\nglobalThis.installMFOInternalLearning(${JSON.stringify(config.browser)});\n${end}\n` + source;
}

