  'list-collections.json': {sections: {main: {type: `${c.prefix}-list-collections`, settings: {}}}, order: ['main']},
  'search.json': {sections: {main: {type: `${c.prefix}-search`, settings: {}}}, order: ['main']},
  'cart.json': {sections: {main: {type: `${c.prefix}-cart`, settings: {}}}, order: ['main']},
  '404.json': {sections: {main: {type: `${c.prefix}-404`, settings: {}}}, order: ['main']},
  'page.json': {sections: {main: {type: `${c.prefix}-page`, settings: {}}}, order: ['main']},
  'page.about.json': {sections: {main: {type: `${c.prefix}-page`, settings: {}}, business: {type: 'mf-business', settings: {heading: 'Business details', show_details: true, show_form: false}}}, order: ['main', 'business']},
  'page.contact.json': {sections: {main: {type: `${c.prefix}-page`, settings: {}}, business: {type: 'mf-business', settings: {heading: 'How to reach us', show_details: true, show_form: true}}}, order: ['main', 'business']},
  'blog.json': {sections: {main: {type: `${c.prefix}-blog`, settings: {}}}, order: ['main']},
