export const CSV_HEAD = ['Handle', 'Title', 'Body (HTML)', 'Vendor', 'Type', 'Tags', 'Published', 'Option1 Name', 'Option1 Value', 'Variant SKU', 'Variant Grams', 'Variant Inventory Tracker', 'Variant Inventory Qty', 'Variant Inventory Policy', 'Variant Fulfillment Service', 'Variant Price', 'Variant Requires Shipping', 'Variant Taxable', 'Gift Card', 'SEO Title', 'SEO Description', 'Status'];
const csvCell = v => /[",\n]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v);
export function productCsv(c) {
  const rows = c.products.map(p => {
    const kind = c.kinds[p.kind] || p.kind;
    const body = `<p>${esc(p.note)}</p><ul>${p.facts.map(f => `<li>${esc(f)}</li>`).join('')}</ul><p>Price snapshot: ${esc(p.price)} at ${esc(p.merchant)}, checked ${longDate(p.checked || c.checked)}.</p>`;
    return [p.handle, p.name, body, p.brand, kind.replace(/s$/, ''), ['kind:' + p.kind, 'maker:' + slug(p.brand), 'research-record'].join(', '), 'TRUE', 'Title', 'Default Title', p.handle, '0', 'shopify', '0', 'deny', 'manual', '0.00', 'FALSE', 'FALSE', 'FALSE', `${p.brand} ${p.name} | ${c.name}`, p.note.slice(0, 155), 'active'];
  });
  return [CSV_HEAD, ...rows].map(r => r.map(csvCell).join(',')).join('\n') + '\n';
}

/** Every generated file as {path (relative to shopify/), text|buffer}. */
export function files(c = loadCatalog()) {
  const P = PROFILES[c.profile];
  if (!P) throw new Error('Unknown profile ' + c.profile);
  const out = [];
  const add = (p, text) => out.push({path: p, text});
  const sec = (name, text) => add(`theme/sections/${name}.liquid`, text);
  add('theme/layout/theme.liquid', layout(c, P));
  add(`theme/assets/${c.asset}.css`, fs.readFileSync(path.join(root, 'src/parent.css'), 'utf8') + siteCss(c));
  add(`theme/assets/${c.asset}.js`, siteJs());
  sec(`${c.prefix}-announcement`, `${GEN}${P.announcement(c)}\n${schema({name: 'Announcement', settings: []})}`);
  sec(`${c.prefix}-header`, `${GEN}${P.header(c)}\n${schema({name: 'Header', settings: []})}`);
  sec(`${c.prefix}-footer`, `${GEN}${P.footer(c)}\n${schema({name: 'Footer', settings: []})}`);
  add('theme/sections/header-group.json', JSON.stringify({type: 'header', name: 'Header group', sections: {announcement: {type: `${c.prefix}-announcement`, settings: {}}, header: {type: `${c.prefix}-header`, settings: {}}}, order: ['announcement', 'header']}, null, 2) + '\n');
  add('theme/sections/footer-group.json', JSON.stringify({type: 'footer', name: 'Footer group', sections: {footer: {type: `${c.prefix}-footer`, settings: {}}, trust: {type: 'mf-trust', settings: {}}}, order: ['footer', 'trust']}, null, 2) + '\n');
  sec(`${c.prefix}-home`, homeSection(c, P));
  sec(`${c.prefix}-product`, productSection(c));
  sec(`${c.prefix}-collection`, listSection(c, 'Collection', 'collection'));
  sec(`${c.prefix}-search`, listSection(c, 'Search', 'search'));
  sec(`${c.prefix}-list-collections`, listSection(c, 'Collections list', 'collections'));
  sec(`${c.prefix}-cart`, simpleSection(c, 'Cart', `  <p class="mf-room__eyebrow mf-room__eyebrow--gold">Cart</p><h1>There is no checkout here</h1>\n  <p>${esc(c.name)} is a research store. Every piece is bought from its merchant, who sets the price, delivery and returns. Save pieces to your shortlist instead.</p>\n  <p><a class="mf-room__buy" href="{{ routes.root_url }}#shop">Back to the collection</a></p>`));
  sec(`${c.prefix}-404`, simpleSection(c, 'Page not found', `  <p class="mf-room__eyebrow mf-room__eyebrow--gold">404</p><h1>This page is not here</h1>\n  <p>It may have moved. The whole collection is on the home page.</p>\n  <p><a class="mf-room__buy" href="{{ routes.root_url }}#shop">See the collection</a></p>`));
  sec(`${c.prefix}-page`, simpleSection(c, 'Page', `  <h1>{{ page.title | escape }}</h1>\n  <div class="mf-site__rte">{{ page.content }}</div>`));
  sec(`${c.prefix}-blog`, simpleSection(c, 'Blog', `  <h1>{{ blog.title | escape }}</h1>\n  {%- paginate blog.articles by 12 -%}<ul class="mf-room__guide">{%- for article in blog.articles -%}<li><b><a href="{{ article.url }}">{{ article.title | escape }}</a></b>{{ article.excerpt_or_content | strip_html | truncatewords: 30 }}</li>{%- else -%}<li>No guides yet.</li>{%- endfor -%}</ul>{{ paginate | default_pagination }}{%- endpaginate -%}`));
  sec(`${c.prefix}-article`, simpleSection(c, 'Article', `  <p class="mf-room__eyebrow mf-room__eyebrow--gold">{{ blog.title | escape }}</p><h1>{{ article.title | escape }}</h1>\n  <div class="mf-site__rte">{{ article.content }}</div>`));
  sec(`${c.prefix}-password`, `${GEN}<div class="mf-room mf-site__page"><section class="mf-room__band"><div class="mf-room__shell mf-site__prose"><p class="mf-room__eyebrow mf-room__eyebrow--gold">${esc(c.name)}</p><h1>${esc(c.room.title)}</h1><p>{{ shop.password_message | default: 'Opening soon.' | escape }}</p>{%- form 'storefront_password' -%}{{ form.errors | default_errors }}<label for="mf-password">Password</label> <input id="mf-password" type="password" name="password" autocomplete="current-password"> <button type="submit">Enter</button>{%- endform -%}</div></section></div>\n${schema({name: 'Password', settings: []})}`);
  add(`theme/snippets/${c.prefix}-card.liquid`, cardSnippet(c));
  add(`theme/snippets/${c.prefix}-research.liquid`, researchSnippet(c));
  add('theme/layout/password.liquid', `<!doctype html>
<html lang="{{ request.locale.iso_code }}">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <meta name="robots" content="noindex,nofollow">
  <title>{{ shop.name }}</title>
  {{ '${c.asset}.css' | asset_url | stylesheet_tag }}
  {{ content_for_header }}
</head>
<body class="template-password mf-site mf-site--${c.profile}">
  <main id="main">{{ content_for_layout }}</main>
</body>
</html>
`);
  add('theme/templates/gift_card.liquid', `{%- comment -%} Required by Shopify. This store sells no gift cards. {%- endcomment -%}
<!doctype html>
<html lang="{{ request.locale.iso_code }}">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{{ shop.name }}</title>{{ '${c.asset}.css' | asset_url | stylesheet_tag }}</head>
<body><main class="mf-room mf-site__page"><section class="mf-room__band"><div class="mf-room__shell"><h1>{{ shop.name }}</h1><p>Gift card balance: {{ gift_card.balance | money }}</p><p>Code: {{ gift_card.code | format_code }}</p></div></section></main></body>
</html>
`);
  add('theme/config/settings_schema.json', JSON.stringify(settingsSchema(c), null, 2) + '\n');
  add('theme/config/settings_data.json', JSON.stringify({current: {preview_noindex: true}, presets: {Default: {preview_noindex: true}}}, null, 2) + '\n');
  for (const [name, t] of Object.entries(templates(c))) add(`theme/templates/${name}`, JSON.stringify(t, null, 2) + '\n');
  add('products/' + c.site.replace(/^mfo-/, 'many-faces-') + '-products.csv', productCsv(c));
  return out;
}

/** Original media from images/ copied into the theme as assets (only the named slots). */
export function mediaFiles(c = loadCatalog()) {
  return mediaSlots(c).filter(s => has(s.file)).map(s => ({from: path.join(imagesDir, s.file), path: `theme/assets/${s.file}`}));
}

export function build({check = false} = {}) {
  const c = loadCatalog();
  const list = files(c), media = mediaFiles(c), differ = [];
  for (const f of list) {
    const target = path.join(root, f.path);
    const same = fs.existsSync(target) && fs.readFileSync(target, 'utf8') === f.text;
    if (same) continue;
    if (check) differ.push(f.path); else { fs.mkdirSync(path.dirname(target), {recursive: true}); fs.writeFileSync(target, f.text); }
  }
  for (const f of media) {
    const target = path.join(root, f.path);
    if (fs.existsSync(target) && fs.readFileSync(target).equals(fs.readFileSync(f.from))) continue;
    if (check) differ.push(f.path); else { fs.mkdirSync(path.dirname(target), {recursive: true}); fs.copyFileSync(f.from, target); }
  }
  // Fonts travel with the parent stylesheet.
  for (const font of c.fonts || []) {
    const from = path.join(root, 'src/fonts', font), target = path.join(theme, 'assets', font);
    if (fs.existsSync(target) && fs.readFileSync(target).equals(fs.readFileSync(from))) continue;
    if (check) differ.push('theme/assets/' + font); else fs.copyFileSync(from, target);
  }
  if (check) {
    if (differ.length) { console.error('Out of date; run node build.mjs: ' + differ.join(', ')); process.exitCode = 1; }
    else console.log(`${c.name}: theme is current`);
    return;
  }
  // Upload zips (needs the zip tool; skipped without it).
  try {
    const dist = path.join(root, 'dist'); fs.mkdirSync(dist, {recursive: true});
    const base = c.site.replace(/^mfo-/, 'many-faces-');
    fs.rmSync(path.join(dist, base + '-theme.zip'), {force: true}); fs.rmSync(path.join(dist, base + '-products-csv.zip'), {force: true});
    execFileSync('zip', ['-qrX', path.join(dist, base + '-theme.zip'), '.', '-x', '.*'], {cwd: theme});
    execFileSync('zip', ['-qjX', path.join(dist, base + '-products-csv.zip'), path.join(root, 'products', base + '-products.csv')]);
  } catch (e) { console.warn('Zips skipped: ' + e.message.split('\n')[0]); }
  console.log(`${c.name}: wrote ${list.length} files, ${media.length} media files`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) build({check: process.argv.includes('--check')});
